"""Build the English release pages. Firmware binary deliberately stays RC2."""
from pathlib import Path
R=Path(__file__).resolve().parents[1]; D=R/'dist'
def page(name,title,body,manual=False):
    nav='<nav><a class="wordmark" href="./">BUNKER / EVOLVED<span class="brand-dot">●</span></a><a href="./#listen">Listen</a><a href="manual.html">Learn</a><a href="simulator/">Play</a><a href="editor/">Editor</a><a href="install/">Install ↗</a></nav>'
    foot='<footer><div><b>BUNKER / EVOLVED</b><p>A free instrument by Kid Bunka. Built on Felucca, with gratitude to its contributors.</p></div><div><a href="https://github.com/kidbee85-beep/bunker-evolved/releases/tag/v1.0.0">GitHub release</a><a href="Bunker-Evolved-Source.zip">Source + tests</a><a href="comparison.html">What makes it Bunker</a><a href="research.html">Credits & licenses</a><a href="install/test-status.txt">Test report</a><a href="rescue.html">Recovery</a></div><p>Independent firmware for the M-VAVE FM-1. Not affiliated with M-VAVE, Hügelton Instruments, or Dirtywave.<br>Release 1.0 · FM-1_7100002 · GPL-3.0-only and component licenses.</p></footer>'
    (D/name).write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · Bunker Evolved</title><meta name="description" content="Free generative ambient firmware for the FM-1. Four editable layers, 64 sounds, 24 worlds, 32 scales. Listen, learn, play and install."><meta name="theme-color" content="#080a12"><meta property="og:title" content="Bunker Evolved — Let a little world unfold."><meta property="og:image" content="https://bunker-evolved.sugarypixie10.chatgpt.site/media/thumbnail.jpg"><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#content">Skip to content</a><main class="'+('manual' if manual else 'landing')+'">'+nav+'<div id="content">'+body+'</div>'+foot+'</main>'+('<script type="module" src="app.js"></script>' if name=='index.html' else '')+'</body></html>')

page('index.html','A little world of sound','''
<div class="hero"><div><p class="eyebrow"><i></i> FREE AMBIENT FIRMWARE / M-VAVE FM-1</p><h1>Let a little<br>world <span>unfold.</span></h1><p class="intro">Four layers of sound. A melody to follow.<br>Just enough surprise to make it your own.</p><div class="actions"><a class="button" href="simulator/">Play in your browser <span>↗</span></a><a class="button secondary" href="install/">Get the firmware</a></div><p class="micro">Release 1.0 · Free & open source · Original ↔ Bunker update tested by the owner</p></div><div class="hero-instrument"><img src="media/panel.svg" class="instrument-panel" alt="FM-1 front-panel illustration with its physical knob and key layout"><img class="instrument-screen" src="grow-motion.webp" alt="Actual GROW display rendered by the firmware: four coloured note tracks"><span class="instrument-caption">ACTUAL FIRMWARE DISPLAY / ILLUSTRATED PANEL</span><div class="orbit-label">SMALL INSTRUMENT.<br>OPEN POSSIBILITIES.</div></div></div>
<div class="strip"><div><strong>4<span> / layers</span></strong><p>AIR · MELODY · ROOT · SPARK</p></div><div><strong>64<span> / sounds</span></strong><p>READY TO PLAY. YOURS TO EDIT.</p></div><div><strong>24<span> / worlds</span></strong><p>COMPLETE MUSICAL STARTING POINTS</p></div><div><strong>32<span> / scales</span></strong><p>A DIFFERENT COLOUR IN EVERY KEY</p></div></div>
<section id="film"><div class="section-head"><div><p class="eyebrow">01 / MEET YOUR NEXT QUIET OBSESSION</p><h2>Listen. Then make it yours.</h2></div><p>A guided introduction with calm English narration, actual firmware screens, and music from the C audio engine.</p></div><video controls playsinline preload="metadata" poster="media/thumbnail.jpg" aria-label="Bunker Evolved introduction and tutorial"><source src="media/Bunker-Evolved-Introduction.mp4" type="video/mp4"><track kind="captions" src="media/Bunker-Evolved-English.vtt" srclang="en" label="English">Your browser does not support this video. <a href="media/Bunker-Evolved-Introduction.mp4">Download the video.</a></video><p class="micro video-note">English narration · Optional captions · Rendered demonstration, not camera footage of a device. <a href="https://www.youtube.com/watch?v=NJ5UFi62s_0">Watch on YouTube</a> · <a href="media/Bunker-Evolved-Introduction.mp4" download>Download film</a> · <a href="media/Bunker-Evolved-English.srt" download>Captions</a> · <a href="Bunker-Evolved-Publication-Kit.zip" download>Publication kit</a></p></section>
<section class="grow-feature"><div><p class="eyebrow">02 / A FRIENDLY WAY TO FIND THE NEXT PHRASE</p><h2>Choose a scale.<br>Give it a little <em>GROW.</em></h2><p class="muted">Set the key and scale. Pick a gentle variation or a fresh direction. Press OCT+ and listen. One track or all melodic tracks — your sound and mix stay yours.</p><div class="grow-styles"><div><b>TUNE</b><span>Fit the scale</span></div><div><b>SOFT</b><span>Small steps</span></div><div><b>FLOW</b><span>More movement</span></div><div><b>NEW</b><span>A fresh phrase</span></div></div><p class="micro">Not quite it? OCT− undoes the last GROW step. The new phrase is locked while you decide.</p><a href="manual.html#grow">Learn GROW in one minute →</a></div><div class="display-portrait"><img src="grow-motion.webp" alt="Original 240 by 240 GROW display"><div class="control-caption"><span>OCT− / UNDO</span><span>OCT+ / GROW</span></div></div></section>
<section><div class="section-head"><div><p class="eyebrow">YOUR INSTRUMENT / YOUR NOTES</p><h2>Make it yours.<br>One layer at a time.</h2></div><p>Open the Chrome editor to shape your FM-1 over USB: sound recipes, notes, motifs and gentle variations in 32 scales.</p></div><div class="actions"><a class="button" href="editor/">Open the editor ↗</a><a href="comparison.html">What makes it Bunker →</a></div><p class="micro">Editor 0.1 · New browser component · Firmware 1.0 stays unchanged.</p></section><section id="listen"><div class="section-head"><div><p class="eyebrow">03 / FIND A PLACE TO BEGIN</p><h2>Twenty-four worlds.<br>No two have to stay the same.</h2></div><p>Real synthesis, rendered from the firmware's audio code. Each 16-second preview is a starting point. Open the instrument to change it and let it run.</p></div><div id="worlds" class="worlds"></div><p id="audioStatus" role="status" class="micro">Press play to listen. One preview plays at a time.</p></section>
<section><div class="section-head"><div><p class="eyebrow">04 / THE SOUND IS STILL IN YOUR HANDS</p><h2>From glass to grain.</h2></div><p>Sixteen sound recipes for each musical role. All four tracks remain freely editable, with thirteen synthesis engines underneath.</p></div><div class="tabs" role="tablist" aria-label="Sound role"><button role="tab" aria-selected="true" data-role="0">AIR</button><button role="tab" aria-selected="false" data-role="1">MELODY</button><button role="tab" aria-selected="false" data-role="2">ROOT</button><button role="tab" aria-selected="false" data-role="3">SPARK</button></div><div class="sounds" id="sounds"></div><div class="engine-line">ANALOG · PHASE · LOFI · SAMPLE · VOICE · TRIO · WHEEL · GRAIN · PHYS · DRUM · NOISE · FM6 · SLICE</div><p class="muted">Shape the engine, envelopes, LFO and effects. Replace a single note or play a chord into the sequencer. Save your sounds and complete compositions.</p></section>
<section class="two"><div><p class="eyebrow">05 / MAKE SPACE FOR CHANGE</p><h2>A phrase can wander.<br>You decide how far.</h2><p class="muted">Seven EVOLVE processes add controlled variation to the real sequence. Set the chance and the number of loops between changes. Lock the phrase whenever you find something worth keeping.</p><p class="engine-line">WALK / ANSWER / ORBIT / MIRROR / BLOOM / BREATH / VOICE</p><a href="manual.html#evolve">Meet the seven processes →</a></div><div class="callout"><h3>One panel. Six musical views.</h3><ol class="checklist"><li><b>WORLD</b> — load a complete composition.</li><li><b>GROW</b> — find a new phrase in your scale.</li><li><b>SOUND</b> — choose a voice and shape it.</li><li><b>MOTIF</b> — change the pattern and rhythm.</li><li><b>EVOLVE</b> — set movement, then let it happen.</li><li><b>MIX</b> — bring the four layers together.</li></ol></div></section>
<section class="two"><div><p class="eyebrow">06 / MADE TO BE PLAYED. OPEN TO BE UNDERSTOOD.</p><h2>A small gift<br>to curious musicians.</h2><p class="muted">Bunker Evolved builds on Felucca's synthesis, editors, storage and hardware support. The ambient library, musical front page and generative tools are Bunker's contribution.</p><p class="muted">The complete source, build instructions, credits and test results are available. No account, subscription or payment is required by the instrument.</p><a href="research.html">Read the credits →</a></div><div><h3>Ready to explore?</h3><p class="muted">Try the exact C program in the browser. For your FM-1, follow the installation guide and keep the recovery page nearby.</p><div class="actions"><a class="button" href="install/">Install Bunker Evolved ↗</a><a class="button secondary" href="manual.html">Read the guide</a></div><p class="micro">The owner completed the original → Bunker → original update cycle on an FM-1 and confirmed working audio and controls. Automated tests cover generation, storage, audio and update logic. See the <a href="release.html">release notes</a>.</p></div></section>
''')

page('manual.html','The field guide','''
<header class="page-head"><p class="eyebrow">THE FIELD GUIDE / RELEASE 1.0</p><h1>Find a phrase.<br><span>Follow it.</span></h1><p>Start with the six Bunker pages. Go deeper with the FM-1's dedicated editor buttons whenever you want.</p><div class="chapter-links"><a href="#quickstart">First minutes</a><a href="#grow">GROW</a><a href="#controls">Controls</a><a href="#evolve">EVOLVE</a><a href="#notes">Notes</a><a href="#save">Save</a></div></header>
<section id="quickstart"><h2>Your first two minutes</h2><ol><li>Turn the master volume down, connect headphones or speakers, then press <b>PLAY</b>. On a fresh start, Violet Dawn is ready. A restored project may contain different music.</li><li><b>ALGORITHM</b> selects AIR, MELODY, ROOT or SPARK. These are roles, not fixed engines.</li><li><b>HOME</b> cycles WORLD → GROW → SOUND → MOTIF → EVOLVE → MIX. SELECT also changes pages. From another editor, HOME first returns to WORLD.</li><li>On SOUND, turn PRESETS or KNOB 1 to load one of the selected layer's sixteen sounds. KNOB 2 changes colour, KNOB 3 release, KNOB 4 reverb.</li><li>To try another world: stop playback, choose it on WORLD with PRESETS or KNOB 1, then press <b>OCT+</b>. This replaces the composition, so save anything you want to keep.</li></ol><p class="callout">The four fields at the top of the display correspond to KNOB 1–4. MASTER always controls the output level. On the advanced Felucca editors, the encoders retain those editors' functions.</p></section>
<section id="grow"><p class="eyebrow">THE EASY MELODIC TOOL</p><h2>GROW, one step at a time</h2><div class="two"><div><ol><li>From WORLD press HOME once. Select a track with ALGORITHM.</li><li><b>KNOB 1:</b> choose the root note.</li><li><b>KNOB 2:</b> choose the scale.</li><li><b>KNOB 3:</b> choose TUNE, SOFT, FLOW or NEW.</li><li><b>KNOB 4:</b> choose ONE or ALL melodic tracks.</li><li><b>OCT+:</b> apply. <b>OCT−:</b> undo the last GROW.</li></ol></div><div><img class="guide-screen" src="grow-motion.webp" alt="Actual GROW display"></div></div><table><tr><th>Style</th><th>What changes</th></tr><tr><td>TUNE</td><td>Fits existing notes to the chosen root and scale.</td></tr><tr><td>SOFT</td><td>Small changes by neighbouring scale degrees.</td></tr><tr><td>FLOW</td><td>More frequent and wider melodic movement.</td></tr><tr><td>NEW</td><td>A fresh variation over the existing rhythm. Creates a sparse motif if the track is empty.</td></tr></table><p>Knob choices are a draft until OCT+ is pressed. Sounds, levels, note lengths and existing rhythm remain intact. DRUM and SLICE tracks are skipped. The selected notes fit the scale and are kept in MIDI range 24–108.</p><p>GROW also works during playback. It sets the affected tracks to LOCK so you can compare the phrase without further automatic changes. Return to EVOLVE to enable ongoing movement again.</p><p>Undo restores one complete GROW operation, including the previous scale and evolution mode. A newer GROW replaces this undo point. If you edit the affected phrase elsewhere, an older undo is refused to protect newer work. Undo history is lost on restart. GROW is unavailable during recording or a running song chain.</p></section>
<section id="controls"><h2>The six pages</h2><div class="screen-gallery">'''+''.join(f'<img src="screen-{i}.png" alt="Actual {name} screen">' for i,name in enumerate(['WORLD','GROW','SOUND','MOTIF','EVOLVE','MIX']))+'''</div><div class="table-scroll"><table><tr><th>Page</th><th>KNOB 1</th><th>KNOB 2</th><th>KNOB 3</th><th>KNOB 4</th></tr><tr><td>WORLD</td><td>Choose world</td><td>Global root</td><td>Global scale</td><td>Tempo 30–180</td></tr><tr><td>GROW</td><td>Draft root</td><td>Draft scale</td><td>Style</td><td>ONE / ALL</td></tr><tr><td>SOUND</td><td>Load sound</td><td>Engine colour</td><td>Release</td><td>Reverb send</td></tr><tr><td>MOTIF</td><td>Choose template</td><td>Density 1–16</td><td>Length 1–64</td><td>Step rate</td></tr><tr><td>EVOLVE</td><td>Mode</td><td>Chance 0–100%</td><td>Every 1–32 loops</td><td>Key transpose*</td></tr><tr><td>MIX</td><td>AIR level</td><td>MELODY level</td><td>ROOT level</td><td>SPARK level</td></tr></table></div><p><b>WORLD:</b> choose a world, stop, then OCT+ to load. Root and scale change the notes of all tracks immediately. Repeated quantisation is not reversible; use GROW with undo for comparisons or reload a saved project.</p><p><b>MOTIF:</b> OCT+ applies the chosen template and density, replacing the selected track's notes. Length and rate change immediately. Density is the number of distributed hits per sixteen steps. The template name shows your next selection, not an analysis of an edited or restored pattern.</p><p><b>OCT−:</b> mutes the selected track on WORLD, SOUND, MOTIF and MIX. On SOUND and MIX, OCT+ also toggles mute. On GROW it means UNDO; on EVOLVE it means LOCK.</p><p><b>*Key transpose:</b> EVOLVE's fourth knob changes the shared keyboard transpose parameter. In the default SCL → QUANT = SEQ mode it affects live keys, not stored sequence playback. Choose SEQ+T on SCL to transpose sequence playback too. For a simple, permanent scale-based sequence change, use GROW → TUNE.</p></section>
<section id="evolve"><h2>Let the pattern develop</h2><table><tr><th>Mode</th><th>Behaviour</th></tr><tr><td>LOCK</td><td>No automatic note changes. Envelopes, modulation and effect tails continue.</td></tr><tr><td>WALK</td><td>Moves an existing hit by a neighbouring scale degree, keeping its chord together.</td></tr><tr><td>ANSWER</td><td>Copies pitches from another step in the phrase, or moves to a neighbouring note.</td></tr><tr><td>ORBIT</td><td>Rotates the complete pattern by one step.</td></tr><tr><td>MIRROR</td><td>Swaps two complete steps.</td></tr><tr><td>BLOOM</td><td>Moves a hit into a rest, or moves a note upward when that place is occupied.</td></tr><tr><td>BREATH</td><td>Varies velocity and step probability within bounded ranges.</td></tr><tr><td>VOICE</td><td>Moves one chord tone by an octave while preserving its pitch class.</td></tr></table><p>CHANCE is the probability of a change after each chosen number of LOOPS. It is not the probability of every note. For an obvious demonstration, choose WALK, 100%, one loop; or press OCT+ for one immediate step. A random operation may sound unchanged, for example when swapping two rests.</p><p>OCT− locks the current pattern. Evolution pauses during recording and song-chain playback, and excludes DRUM tracks. Notes and evolution settings are saved; the random generator state is not, so the later path may differ after restarting.</p><p>The display shows real track notes, coloured playhead diamonds and the chosen scale. Hold HOME → DISPLAY → ANIM to disable decorative movement. The animation does not control the music.</p></section>
<section id="notes"><h2>Edit individual notes and chords</h2><ol><li>Select a track with ALGORITHM. On EVOLVE, press OCT− to lock it.</li><li>Stop playback and press SEQ for STEP. KNOB 1 selects the step; KNOB 2 transposes its note or chord; KNOB 3 changes length; KNOB 4 changes accent/slide.</li><li>To enter notes, enable REC on the stopped STEP page and press a key. Releasing advances to the next step. Hold several keys together for a chord. Turn REC off when finished.</li><li>Press SEQ again for DETAIL: chance, ratchets, timing offset and velocity. The next page contains automation.</li><li>Press PLAY. Re-enable a mode on EVOLVE when you want the phrase to continue changing.</li></ol><p>The 32 scales are pitch collections in twelve-tone equal temperament, not microtonal tunings. SCL can set the scale independently per track.</p></section>
<section><h2>Go deeper into the sound</h2><table><tr><th>Button</th><th>Opens</th></tr><tr><td>EDIT</td><td>Engine parameters, including detailed FM6 editing.</td></tr><tr><td>ENV</td><td>Attack, decay, sustain, release and envelope controls.</td></tr><tr><td>LFO</td><td>Modulation settings and the modulation matrix.</td></tr><tr><td>FX</td><td>Insert effects, chorus, delay and reverb. Hold for the performance layer.</td></tr><tr><td>SCL / ARP</td><td>Scale, quantisation, chord tools / arpeggiator.</td></tr><tr><td>GLO</td><td>Global settings and, when held, the existing quick functions.</td></tr><tr><td>SAVE</td><td>User sounds, factory presets, phrases, projects and tools.</td></tr></table><p>The original Felucca documentation is included in the source archive. This guide describes Bunker's changed HOME pages. To return from another home view, hold HOME → DISPLAY → HOME → BUNKER.</p></section>
<section id="save"><h2>Keep what you make</h2><p>Stop playback. Press SAVE until PROJECT appears. KNOB 1 selects slot A–D; KNOB 4 selects SAVE; press OCT+. Confirm any overwrite and name dialogue. Choose LOAD on the same page to return to it. SAVE → USER offers 32 user sound slots.</p><p>For an external Bunker backup, use <a href="install/#backup">Back up your music</a> on the installer while the device is stopped. Restore it only to compatible Bunker firmware. Autosave is helpful, but it is not an external backup.</p><p>This release uses the Bunker 114-parameter project format. Other firmware projects are not converted. Felucca 1.6.1 cannot load Bunker's 114-parameter projects. A firmware rollback does not bring back overwritten music.</p></section>
<section><h2>A little room to breathe</h2><p>The four tracks share eight voices. Long releases and dense chords may steal voices. The inherited overload protection fades a voice after repeated overloaded blocks. The watchdog remains active; the experimental second CPU core is disabled in this build.</p><p>For dense textures, try two or three notes per chord, fewer simultaneous hits and shorter releases. The browser runs the real DSP, but it cannot measure the FM-1 chip's timing margin or test its USB and flash hardware.</p><p><a href="release.html">Read the verification notes</a> or <a href="rescue.html">open the recovery guide</a>.</p></section>
<section><h2>Play without hardware</h2><p><a href="simulator/">Open the browser instrument</a>, click Power on, then PLAY. Drag knobs or use the mouse wheel. Keyboard shortcuts are shown below the panel. The wide layout follows the FM-1 panel; the phone layout rearranges controls for readability.</p><p>The simulator needs an AudioWorklet at 44.1 kHz. Its projects stay in this browser's local storage and are not automatically transferred to hardware. Close it and other MIDI applications before flashing a device.</p></section>
''',True)

page('rescue.html','Recovery guide','''
<header class="page-head"><p class="eyebrow">KEEP THIS PAGE BEFORE YOU UPDATE</p><h1>A way<br><span>back.</span></h1><p>Recovery depends on what still responds. The normal MIDI update loader and the chip's UBOOT mode are different things.</p></header>
<section><h2>1 / The FM-1 still starts</h2><p>Open the <a href="install/">installer</a>, detect the device and back up Bunker music while stopped. Choose Original V15 to return to the manufacturer’s firmware. Older alternatives remain under “Other firmware / archive” in the installer. For V15, download the manufacturer's unchanged FM-1.fwsc and select it locally. Its SHA-256 must match the known package. Install and wait for the final identity check.</p><p>Other firmwares do not automatically understand Bunker projects. Restore Bunker first if you later want to restore a Bunker music backup.</p></section>
<section><h2>2 / An update was interrupted</h2><p>Keep the device powered. Save the installer log. Close other MIDI programs, reconnect in the installer and choose the same target package. If <code>ota-FM-1</code> answers, the installer restarts the writing phase from the beginning. It does not resume at the last byte.</p><p>Do not repeatedly unplug or reboot while writes may be in progress. The browser only reports success after a responding application returns the expected firmware identity.</p></section>
<section><h2>3 / The application hangs</h2><p>The inherited watchdog can restart a stalled application after approximately eight seconds. Two failed starts within the initial startup window can enter UBOOT, the chip update mode. This is not a normal MIDI safe mode.</p><p>Holding both OCT− and OCT+ for five seconds <b>while the application is running</b> also enters UBOOT. Do this only when following a chip-recovery procedure. Holding the same keys <b>at power-on</b> enters panel calibration instead.</p></section>
<section><h2>4 / No compatible MIDI device answers</h2><p>The browser installer cannot reach every failed application or chip mode. Check the data cable, power and USB port; record the screen state and save any available log. Use the <a href="https://www.m-vave.com/download">manufacturer's downloads and M-UPGRADE tools</a> or the community's <a href="https://github.com/kurogedelic/FM-1-transporter">FM-1 transporter documentation</a> for the mode actually detected.</p><p>A chip-mode recovery may need separate tools and cannot be promised through Chrome. Do not erase flash sectors, write a raw .bin, or follow a procedure for an unconfirmed board. The normal tested loader preserves the protected boot header and calibration region.</p></section>
<section><h2>What is protected — and what is not</h2><p>Bunker keeps the existing eight-voice budget, overload fade and watchdog. There is no hidden remote-access backdoor and no replacement bootloader. These measures limit software overload and help recover from hangs; they do not make power loss during flashing harmless.</p><p>On 17 October 2026, the owner confirmed the complete original → Bunker → original update cycle, with working audio and controls. This normal-update test did not test interrupted power. Do not provoke a power failure as a test.</p><div class="actions"><a class="button" href="install/">Open the installer ↗</a><a class="button secondary" href="release.html">Verification details</a></div></section>
''',True)

page('research.html','Built on open work','''
<header class="page-head"><p class="eyebrow">SOURCE / CREDIT / COMMUNITY</p><h1>Built on<br><span>open work.</span></h1><p>Bunker Evolved is a Felucca fork with a new ambient composition layer. Credit belongs to the people who made the instrument beneath it possible.</p></header>
<section><h2>Why Felucca?</h2><p>The <a href="https://github.com/cicloid/awesome-fm-1">FM-1 firmware catalogue</a> and documentation from eighteen projects informed the choice. Felucca offered four freely assignable synthesis tracks, thirteen active engines, deep editors, project storage and an extensive host test suite. This was a feature comparison, not a security audit of every firmware.</p><table><tr><th>Project</th><th>What informed the choice</th></tr><tr><td><a href="https://github.com/hugelton/Felucca">Felucca 1.6.1</a></td><td>The chosen base: four editable tracks and deep sound design. The original author has stepped back from active development; this fork needs its own maintenance.</td></tr><tr><td><a href="https://github.com/charlesvestal/fm1-amb">AMB-1</a></td><td>Immediate generative soundscapes and approachable operation.</td></tr><tr><td><a href="https://github.com/isod89/sloop-fm1">Sloop</a></td><td>Performance and sequencing tools, organised around three synth tracks and a drum track.</td></tr><tr><td>MAKU / MIN-1 / UnholyUnion</td><td>Ambient gestures and constrained musical processes, with different editing trade-offs.</td></tr><tr><td>Melodee Tess / FiMba / Niagara Drift</td><td>Generative structures and specialist instruments; different architectures and scope.</td></tr></table><p>Other documented comparisons include Tonitor, DUELL, ChoralRoot, TripDeck, Patricktronics, X0X, FoMni, Melodee and GHOULBOX. Research snapshots are included under docs/research in the source.</p></section>
<section><h2>How this differs from Felucca</h2><p><a href="comparison.html">Read the feature-by-feature comparison and provenance</a>, including concrete overlaps with AMB-1, Sloop, MAKU and UnholyUnion.</p></section><section><h2>What Bunker adds</h2><p>Six musical HOME pages; 64 editable sound recipes; 24 worlds; 24 motif templates; 32 scales; seven bounded sequence transformations plus LOCK; GROW with scale-based variations and one-step undo; coloured note animation; a browser instrument and a checked installer.</p><p>The synthesis engines, advanced editors, hardware layer, USB/MIDI, persistence and update loader derive from Felucca and its credited dependencies. Bunker's composition tools edit the actual stored sequencer notes. Turing, Markov and seamless world morphing are not part of this release.</p></section>
<section><h2>Attribution and licenses</h2><p>Felucca by Leo Kuroshita (@kurogedelic), Hügelton Instruments. Base commit: <code>5738617968a22b5d4c0d3470cfcc95559052f446</code>. Vendored Felucca-Engines: <code>c46e0086f69bdc26df1cd144dca9e683cc4531dd</code>. Browser work also derives through Felucca from Charles Vestal's X0X.</p><p>Main software license: GPL-3.0-only. Engine code retains MIT notices, MSFA and SDK components retain Apache-2.0 notices, samples are CC0, and fonts retain their font licenses. All original attributions and the corresponding source are included.</p><p>Direction: Kid Bunka. Development, documentation and testing used AI assistance. The video uses an AI-generated English narrator; its music is generated by the firmware's synthesis code. Display graphics are rendered from that code, and the panel is an illustration. No Dirtywave M8 artwork is included.</p><div class="actions"><a class="button" href="Bunker-Evolved-Source.zip">Download source + tests</a><a href="licenses/LICENSING.md">Component licenses</a><a href="licenses/CREDITS.md">Upstream credits</a></div></section>
''',True)

page('release.html','Release and verification','''
<header class="page-head"><p class="eyebrow">RELEASE RECORD / 17 OCTOBER 2026</p><h1>Bunker Evolved.<br><span>Release 1.0.</span></h1><p>Released after the project owner completed the original → Bunker → original update cycle on an FM-1 and confirmed working audio and controls. The released firmware is byte-for-byte identical to the hardware-tested build.</p></header>
<section><h2>Chrome editor 0.1</h2><p>The <a href="editor/">new editor</a> is a separate website component. It has 49,337 host assertions against the actual C handler and DOM interaction checks; physical USB acceptance and browser visual QA remain pending. It requires no additional firmware flash. <a href="editor-architecture.html">Scope and architecture →</a></p></section><section><h2>Package identity</h2><table><tr><th>Release</th><td>Bunker Evolved 1.0 · 17 October 2026</td></tr><tr><th>Internal build label</th><td>BE 1.0-RC2 (retained in the tested firmware)</td></tr><tr><th>Device identity</th><td><code>FM-1_7100002</code></td></tr><tr><th>Package size</th><td>610,090 bytes</td></tr><tr><th>SHA-256</th><td class="hash">db0b50d0ae9c3bfccee76e3b93de09fffa55389169278a0c5899dad9c79e6bb8</td></tr></table><p>Release 1.0 promotes the tested build without recompiling or changing its bytes. Its startup label still contains RC2. If you already run FM-1_7100002, you have this exact release and do not need to flash again.</p></section>
<section><h2>Verified, with clear boundaries</h2><ul><li>Owner hardware acceptance, 17 October 2026: Bunker → original, original → Bunker, then Bunker → original completed. Audio and controls worked. This is a report from one FM-1, not independent certification or a test of every board revision.</li><li>19 defined native regression suites; additional Bunker panel and library checks.</li><li>GROW: 3,309,372 assertions across all keys, scales and styles, including undo and persistence.</li><li>One-hour simulated-audio stress run: 3,606.5 seconds, at most eight voices. Additional 1,202.5 seconds with ASan and selected UBSan checks.</li><li>C and WebAssembly rendering match bit for bit for 88,200 stereo frames.</li><li>Modelled RC1 ↔ RC2 loader tests preserve protected boot and user regions. Browser update protocol tests cover malformed requests, disconnects, completion identity and retry.</li></ul><p>Host tests cannot establish physical USB reliability, chip CPU headroom, battery behaviour or power-loss recovery. The owner’s normal original-firmware round trip is now recorded. Original V15 remains the documented installer baseline; the owner did not separately record the stock version string.</p><a href="install/test-status.txt">Detailed report and limitations →</a></section>
<section><h2>Installing from original firmware</h2><p>The direct route is original FM-1 firmware → Bunker Evolved using the same M-UPGRADE-compatible MIDI protocol. The owner has completed this route and the return to original firmware. AMB-1 is not an intermediate requirement. Original V15 is the documented baseline. If an older original version does not enter update mode, use the manufacturer's supported updater to reach V15 first.</p><p>Back up data with tools appropriate to the firmware currently installed. Bunker's backup button supports compatible Bunker builds; it does not export proprietary stock or AMB music. Review the <a href="rescue.html">recovery guide</a> before writing.</p></section>
''',True)

page('comparison.html','What makes it Bunker','''
<header class="page-head"><p class="eyebrow">OUR INGREDIENTS / OPENLY CREDITED</p><h1>A new way in.<br><span>Deep roots underneath.</span></h1><p>Bunker Evolved combines curated ambient worlds and simple, reversible composition gestures with Felucca’s deep sound editing. That combination is its focus.</p></header>
<section><h2>The Bunker difference</h2><div class="feature-grid"><article><h3>Start with a world</h3><p>24 curated arrangements and 64 role-specific sound recipes give AIR, MELODY, ROOT and SPARK a musical starting point.</p></article><article><h3>Keep the melody yours</h3><p>24 motifs, 32 scales and GROW’s TUNE / SOFT / FLOW / NEW turn a phrase into editable notes. Keep a variation, undo it, or let EVOLVE continue.</p></article><article><h3>Go deeper when you want</h3><p>The approachable HOME pages sit beside Felucca’s synthesis, modulation, sequencing and project tools. The sound remains yours to shape.</p></article></div></section>
<section><h2>Compared with our Felucca 1.6.1 base</h2><table><thead><tr><th>Area</th><th>Felucca foundation</th><th>Bunker’s addition</th></tr></thead><tbody><tr><td>Sound</td><td>Engines, factory presets, filters, envelopes, modulation and effects.</td><td>64 ambient sound recipes and 24 curated worlds. Recipes use and reshape existing sounds.</td></tr><tr><td>Composition</td><td>Four tracks, step sequencing, patterns, chance, conditions, arp and scale tools.</td><td>24 scale-degree motifs; seven bounded sequence transformations with per-track chance, interval and LOCK.</td></tr><tr><td>Harmony</td><td>16 scales in the pinned base.</td><td>16 further established scales, bringing the menu to 32; a friendly GROW workflow with undo.</td></tr><tr><td>Interface</td><td>Hardware controls and full editing infrastructure.</td><td>Six ambient HOME pages, four musical roles, Bunker colours and note animation.</td></tr><tr><td>Browser</td><td>A web editor, simulator, installer and the MIDI/SysEx protocol already exist upstream.</td><td>A focused, modular ambient editor and Bunker’s release website, instrument, guides and tests.</td></tr></tbody></table><p>Compared against <a href="https://github.com/hugelton/Felucca/tree/5738617968a22b5d4c0d3470cfcc95559052f446">Felucca 1.6.1 at the exact source commit used</a>. The <a href="https://github.com/hugelton/Felucca/blob/5738617968a22b5d4c0d3470cfcc95559052f446/firmware/src/params.c">base scale table</a> records its 16 entries. This is a description of differences, not a claim that Bunker sounds better or is safer.</p></section>
<section><h2>Good ideas have neighbours</h2><table><tr><th>Project</th><th>What it already explores</th></tr><tr><td><a href="https://github.com/charlesvestal/fm1-amb">AMB-1</a></td><td>Generative ambient, four musical layers, curated pieces, editable scale notes and grow/freeze gestures.</td></tr><tr><td><a href="https://github.com/isod89/sloop-fm1/blob/main/GUIDE.md">Sloop</a></td><td>Three synth tracks plus drums, scales/chords and detailed sequencing with chance, ratchets, nudge and parameter locks.</td></tr><tr><td><a href="https://github.com/okumurari2/maku">MAKU</a></td><td>Random in-key ambience, four roles and musical macros. Its design removes deep Felucca editing; Bunker retains those editing paths.</td></tr><tr><td><a href="https://github.com/actuallysparky/FM-1-Unholy-Union-generative-drone-firmware">UnholyUnion</a></td><td>Shared-key ambient arrangements, timed evolution, checkpoints/undo and a browser editor.</td></tr></table><p>We did not invent generative ambient, musical scales, random walks, undo or a browser editor. Our contribution is the particular library, composition code, musical workflow and presentation. We make no “world first” claim.</p></section>
<section><h2>Follow the source</h2><p><code>bunker_library.inc</code> contains the recipes, motifs and worlds; <code>bunker_gen.c</code> implements EVOLVE; <code>bunker_grow.c</code> implements GROW; <code>bunker_ui.c</code> and <code>bunker_draw.c</code> implement the front panel. The new editor lives in <code>dist/editor/</code>. These files and retained upstream notices are in the complete source package.</p><div class="actions"><a class="button" href="Bunker-Evolved-Source.zip">Complete corresponding source</a><a href="feature-provenance.md">Detailed provenance →</a><a href="research.html">Credits & licences →</a></div></section>
''',True)
page('editor-architecture.html','A foundation for future apps','''
<header class="page-head"><p class="eyebrow">EDITOR / PORTABLE BY DESIGN</p><h1>One musical core.<br><span>Room to grow.</span></h1><p>The Chrome editor is available now. Native mobile, desktop and plug-in versions are future development paths.</p><a class="button" href="editor/">Open the editor ↗</a></header>
<section><h2>Separate parts, a shared instrument</h2><table><tr><th>Part</th><th>Responsibility</th></tr><tr><td>Music core</td><td>Notes, scales, seeded variations, motifs and a versioned phrase format. No dependency on the page or USB.</td></tr><tr><td>Device service</td><td>Reads the firmware, applies values, verifies replies and protects phrase undo from later changes.</td></tr><tr><td>Connection adapter</td><td>Web MIDI today. A native MIDI bridge can take its place in an iOS, iPadOS or macOS shell.</td></tr><tr><td>Interface</td><td>Responsive controls for all four layers. The presentation can change without rewriting the music model.</td></tr></table></section>
<section><h2>What is available today</h2><p>All four tracks, 64 Bunker sound recipes, factory presets, sound controls, EVOLVE, 24 motifs, 32 scales, GROW for the selected layer, note editing and phrase import/export. The offline sketchpad is silent; the separate browser instrument provides synthesis. Full WORLD loading remains on the device.</p><p>Editor 0.1 uses the existing firmware protocol. No firmware change or additional flash is needed. The host tests exercise the actual C handler; physical USB acceptance for this new editor remains pending.</p></section>
<section><h2>The next platforms</h2><p>A native app needs MIDI permissions, lifecycle and file handling. A DAW controller plug-in additionally needs host automation, saved state and tempo/MIDI integration. A standalone AU or VST instrument also needs a native audio engine with proper real-time scheduling and host validation. Those products are not included in this release.</p><a href="editor-architecture.md">Read the implementation map and verification instructions →</a></section>
''',True)
